; load.asm -- chapter 50: a tape loader in the cartridge
; generated by gen50.py
        INCLUDE "msx.inc"
        OUTPUT "load.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
hdr     EQU VARS + $10          ; the header block: 16 bytes
start   EQU VARS + $20          ; the data block's three addresses
end     EQU VARS + $22
exec    EQU VARS + $24
left    EQU VARS + $26          ; bytes still to load
bar     EQU VARS + $28          ; the progress bar's next column
ptr     EQU VARS + $2A          ; where the next byte goes
; A tape loader in the cartridge. C-BIOS has no tape routines: the cartridge
; reads the cassette input itself and loads the binary file SCREEN at the
; address its data block gives, then shows the picture the file holds.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, t_look
        ld bc, $0202
        call puts
        VDP_REG 1, $C0          ; display on: the page, while it loads
        in a, (PPI_C)
        and %11101111           ; bit 4 = 0: the motor turns
        out (PPI_C), a
        ld a, 14
        out (PSG_ADDR), a       ; R14 from now on: bit 7 is the tape
        in a, (PSG_READ)
        ld e, a                 ; E: the input as last read
find:   call header             ; D: the threshold, from the tone
        ld hl, hdr
        ld b, 16
.hd:    push bc
        push hl
        call getbyte
        pop hl
        pop bc
        ld (hl), a              ; the header block
        inc hl
        djnz .hd
        ld hl, hdr
        ld b, 10
.d0:    ld a, (hl)
        cp $D0
        jr nz, find             ; not ten $D0: not a binary file
        inc hl
        djnz .d0
        push de
        ld hl, t_thr
        ld bc, $0402
        call puts
        pop de
        push de
        ld a, d                 ; the threshold, shown
        ld bc, $0412
        call putdec
        pop de                  ; putdec uses DE: D and E back
        ld b, 6
        ld c, 2
        ld hl, t_name
        call puts
        inc c
        ld hl, hdr + 10         ; the six characters of the name
        ld b, 6
.nm:    ld a, (hl)
        push bc
        ld b, 6
        call putc
        pop bc
        inc c
        inc hl
        djnz .nm
        call header             ; the data block's tone: D again
        ld hl, start
        ld b, 6
.ad:    push bc
        push hl
        call getbyte
        pop hl
        pop bc
        ld (hl), a              ; start, end, exec: low byte first
        inc hl
        djnz .ad
        ld hl, (end)
        ld bc, (start)
        or a
        sbc hl, bc
        inc hl
        ld (left), hl           ; END is the last byte: END - START + 1 bytes
        ld a, 2
        ld (bar), a
        ld hl, (start)
        ld (ptr), hl
.load:  call getbyte
        ld hl, (ptr)
        ld (hl), a              ; a byte of the file
        inc hl
        ld (ptr), hl
        ld a, l
        and 63
        call z, tick            ; a box every 64 bytes
        ld hl, (left)
        dec hl
        ld (left), hl
        ld a, h
        or l
        jr nz, .load
        in a, (PPI_C)
        or %00010000            ; bit 4 = 1: the motor stops
        out (PPI_C), a
        ld b, 8
        ld c, 2
        ld hl, t_from
        call puts
        ld c, 8
        ld a, (start + 1)
        call puthex
        ld a, (start)
        call puthex
        ld c, 18
        ld a, (end + 1)
        call puthex
        ld a, (end)
        call puthex
        ld hl, t_done
        ld bc, $0C02
        call puts
loaded: ld hl, (start)          ; the file: names, colours, shapes
        VDP_REG 1, $80          ; display off
        VRAM_WRITE $1800
        ld bc, 768
        call copy
        VRAM_WRITE $2000
        ld bc, 32
        call copy
        VRAM_WRITE $0000
        push hl
        ld hl, (end)
        ld de, (start)
        or a
        sbc hl, de
        ld de, -800 + 1
        add hl, de
        ld b, h
        ld c, l                 ; the rest of the file: the shapes
        pop hl
        call copy
        VDP_REG 1, $C0          ; display on: the picture
done:   jr done

; tick: one more box on the progress bar. Keeps DE
tick:   ld a, (bar)
        ld c, a
        inc a
        ld (bar), a
        ld b, 10
        ld a, 2                 ; a filled box
        jp putc

; copy: HL = from, BC = bytes -> to the VRAM, from the address set. HL moves on
copy:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, copy
        ret

; pulse: E = the input as last read -> waits for bit 7 of R14 to change.
;        C = the turns it waited, 44 T-states each; 0 if the edge came
;        before it looked, or if it waited more than 255 turns: a
;        silence ended. E = the input now. Uses A
pulse:  ld c, 0                 ;  8
.wait:  in a, (PSG_READ)        ; 12  bit 7: the tape
        xor e                   ;  5
        jp m, .edge             ; 11  bit 7 changed: an edge
        inc c                   ;  5
        jp nz, .wait            ; 11  44 T-states a turn
.quiet: in a, (PSG_READ)        ; 12  no edge in 256 turns: C = 0, and
        xor e                   ;  5  wait on for the one that ends
        jp p, .quiet            ; 11  the silence
.edge:  xor e                   ;  5  the input again
        ld e, a                 ;  5
        ret                     ; 11

; getbyte: D = the threshold -> A = the next byte on tape. A pulse longer
;          than D turns is half a 0, a shorter one a quarter of a 1. Waits
;          for a start bit, then reads eight bits, the lowest first. Uses
;          BC, L
getbyte:
.start: call pulse              ; 18  the tone, or stop bits: short
        ld a, d                 ;  5
        cp c                    ;  5
        jr nc, .start           ; 13, or 8  until a long one: a start bit
        call pulse              ; 18  its other half
        ld b, 8                 ;  8
.bit:   call pulse              ; 18  a bit's first half
        ld a, d                 ;  5
        cp c                    ;  5  carry: C > D, long: a 0
        jr c, .zero             ; 13, or 8
        call pulse              ; 18  a 1: three more short ones
        call pulse              ; 18
        call pulse              ; 18
        scf                     ;  5  the bit is 1
        jr .next                ; 13
.zero:  call pulse              ; 18  a 0: its other long half
        or a                    ;  5  the bit is 0
.next:  rr l                    ; 10  into L from the top: the lowest comes first
        djnz .bit               ; 14, or 9
        ld a, l                 ;  5
        ret                     ; 11

; header: waits for the tone before a block and measures it: D = twice
;         its mean pulse, in turns. A long pulse is twice a short one, and
;         every pulse is counted low: the work between two pulses eats
;         into them. Uses A, BC, HL
header: call pulse
        ld a, c
        or a
        jr z, header            ; a silence ended: the tone starts
        ld hl, 0                ; the sum of 256 pulses
        ld b, l
.sum:   call pulse              ; 18
        ld a, c                 ;  5
        or a                    ;  5
        jr z, header            ; 13, or 8  a silence: again
        add a, l                ;  5
        ld l, a                 ;  5
        jr nc, .nc              ; 13, or 8
        inc h                   ;  5
.nc:    djnz .sum               ; 14, or 9
        add hl, hl              ; twice the sum
        ld d, h                 ; / 256: twice the mean
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putdec: A = a byte taken as unsigned (0-255): three characters, right-aligned
; putsgn: A = a byte taken as signed (-128 to 127): four characters
;         C moves on by 3 or 4. Uses A, DE, HL.
putdec: push bc
        ld d, ' '
        call digits
        pop bc
        ld hl, numbuf + 1
        ld e, 3
        jr pnout
putsgn: push bc
        ld d, ' '
        bit 7, a                ; the top bit is the sign
        jr z, .pos
        neg                     ; two's complement: the size of the number
        ld d, '-'
.pos:   call digits
        pop bc
        ld hl, numbuf
        ld e, 4
pnout:  ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, pnout
        ret

; digits: A (0-255) into numbuf in decimal, right-aligned, D just left of
;         the first digit. Uses A, C, HL.
digits: ld hl, numbuf
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '            ; HL: the last character
.next:  ld c, 0                 ; C: A divided by 10
.ten:   cp 10
        jr c, .rest
        sub 10
        inc c
        jr .ten
.rest:  add a, '0'
        ld (hl), a              ; the remainder is this digit
        dec hl
        ld a, c
        or a
        jr nz, .next            ; and the quotient is what is left
        ld (hl), d              ; the sign, or a space
        ret
numbuf  EQU VARS                ; 4 bytes of RAM
boxes:  ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000

t_look: db "MOTOR ON: LOOKING FOR A FILE", 0
t_thr:  db "TONE: THRESHOLD", 0
t_name: db "FOUND", 0
t_from: db "FROM $      TO $", 0
t_done: db "LOADED", 0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
